#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: the project board of scrum-github. One stage() per step the human takes.
# Everything above the line before this comment is vendor/pocock/wizard/template.sh, unchanged
# (tests/test_wizard.sh compares them). To change the stages, read vendor/pocock/wizard/SKILL.md.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

SCRUM_CONFIG=".github/scrum.yml"
WIZARD_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
SCRUM_CLI="$WIZARD_DIR/../runtime/bin/scrum"

# write_project_block sets project.enabled, owner and number in SCRUM_CONFIG, touching only
# those lines: yq would drop every blank line of a file it rewrites. With no project block yet,
# the block is appended; otherwise its three keys are replaced in place (a comment after a value
# is kept) and a missing key is added under "project:". yq checks the result, and rewrites the
# file itself if the line edit did not produce it (for example a block written in flow style).
write_project_block() {
  local new want
  new=$(mktemp "${TMPDIR:-/tmp}/scrum-wizard.XXXXXX")
  want="true $PROJECT_OWNER $PROJECT_NUMBER"
  if [[ "$(yq '.project | type' "$SCRUM_CONFIG")" != "!!map" ]] && ! grep -q '^project:' "$SCRUM_CONFIG"; then
    { cat "$SCRUM_CONFIG"
      [[ -z "$(tail -c 1 "$SCRUM_CONFIG")" ]] || printf '\n'
      printf '\nproject:\n  enabled: true\n  owner: %s\n  number: %s\n' "$PROJECT_OWNER" "$PROJECT_NUMBER"
    } > "$new"
  else
    awk -v owner="$PROJECT_OWNER" -v number="$PROJECT_NUMBER" '
      function emit_missing() {
        if (!seen["enabled"]) print "  enabled: true"
        if (!seen["owner"])   print "  owner: " owner
        if (!seen["number"])  print "  number: " number
        seen["enabled"] = seen["owner"] = seen["number"] = 1
      }
      function set(key, value,   rest) {
        rest = $0; sub(/^  [a-z_]+:[ \t]*[^ \t#]*/, "", rest)
        print "  " key ": " value rest; seen[key] = 1
      }
      /^project:[ \t]*(#.*)?$/ { inblock = 1; print; next }
      inblock && /^[^ \t#]/    { emit_missing(); inblock = 0 }
      inblock && /^  enabled:/ { set("enabled", "true"); next }
      inblock && /^  owner:/   { set("owner", owner); next }
      inblock && /^  number:/  { set("number", number); next }
      { print }
      END { if (inblock) emit_missing() }
    ' "$SCRUM_CONFIG" > "$new"
  fi
  if [[ "$(yq '[.project.enabled, .project.owner, .project.number] | join(" ")' "$new" 2>/dev/null)" != "$want" ]]; then
    PROJECT_OWNER="$PROJECT_OWNER" PROJECT_NUMBER="$PROJECT_NUMBER" yq \
      '.project.enabled = true | .project.owner = strenv(PROJECT_OWNER) | .project.number = env(PROJECT_NUMBER)' \
      "$SCRUM_CONFIG" > "$new"
  fi
  cat "$new" > "$SCRUM_CONFIG"
  rm -f "$new"
}

run_wizard() {

TOTAL_STAGES=5
ENV_FILE=/dev/null   # this wizard keeps nothing in a .env file: the token goes to GitHub only

if [[ ! -f "$SCRUM_CONFIG" ]]; then
  printf 'project-board: %s not found. Run this from the root of a repository prepared by scrum init.\n' "$SCRUM_CONFIG" >&2
  exit 1
fi
if ! command -v yq >/dev/null 2>&1 || ! yq --version 2>/dev/null | grep -q mikefarah; then
  printf 'project-board: yq v4 by mikefarah is required (brew install yq).\n' >&2
  exit 1
fi

banner "Scrum project board"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Create the project and link it"
say "The board is a GitHub Project owned by a user or an organization."
ask PROJECT_OWNER "Who owns the project (user or organization login)?"
local base="https://github.com/users/$PROJECT_OWNER"
if confirm "Is $PROJECT_OWNER an organization?"; then base="https://github.com/orgs/$PROJECT_OWNER"; fi
open_url "$base/projects"
step "Create a new project from the Board template."
step "Link the project to this repository."
step "Its Status field needs the options Todo, In Progress and Done (the Board template has them)."
pause "Press Enter when the project exists"
say "The project number is the last part of its URL: .../projects/<number>"
PROJECT_NUMBER=""
while [[ ! "$PROJECT_NUMBER" =~ ^[0-9]+$ ]]; do
  ask PROJECT_NUMBER "Project number:"
  [[ "$PROJECT_NUMBER" =~ ^[0-9]+$ ]] || warn "a number is expected, for example 3"
done

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Turn off the built-in workflows"
say "These workflows change Status on their own and would fight the sync."
open_url "$base/projects/$PROJECT_NUMBER/workflows"
step "Turn off: Item added to project"
step "Turn off: Item closed"
step "Turn off: Item reopened"
step "Turn off: Pull request linked to issue"
step "Turn off: Pull request merged"
note "Auto-add to project and Auto-close issue can stay on."
pause "Press Enter when the five are off"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Create a token and store it as a secret"
say "The workflow token cannot reach Projects, so the sync needs its own token."
open_url "https://github.com/settings/tokens/new?scopes=repo,project&description=scrum-project-sync"
step "Classic token with the scopes repo and project. Give it an expiry date."
step "Generate it and copy it. It is shown once."
note "It is stored only as the repository secret SCRUM_PROJECT_TOKEN, never in a file."
SCRUM_PROJECT_TOKEN_VALUE=""
ask_secret SCRUM_PROJECT_TOKEN_VALUE "Paste the token (hidden):"
if [[ -n "$SCRUM_PROJECT_TOKEN_VALUE" ]]; then
  set_secret SCRUM_PROJECT_TOKEN "$SCRUM_PROJECT_TOKEN_VALUE"
else
  SKIPPED+=("GitHub secret SCRUM_PROJECT_TOKEN (set it manually: gh secret set SCRUM_PROJECT_TOKEN)")
  warn "no token entered; the secret is not set"
fi
SCRUM_PROJECT_TOKEN_VALUE=""
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Turn the board on in $SCRUM_CONFIG"
say "This adds to $SCRUM_CONFIG:"
note "project:"
note "  enabled: true"
note "  owner: $PROJECT_OWNER"
note "  number: $PROJECT_NUMBER"
if confirm "Write it now?"; then
  write_project_block
  printf '  %s✓ wrote%s project block → %s\n' "$GREEN" "$RESET" "$SCRUM_CONFIG"
else
  SKIPPED+=("project block in $SCRUM_CONFIG (enabled: true, owner: $PROJECT_OWNER, number: $PROJECT_NUMBER)")
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Let gh on this machine reach the project"
say "scrum project init runs with your own gh login, which needs the project scope."
if confirm "Run 'gh auth refresh -s project' now? It opens a browser."; then
  gh auth refresh -h github.com -s project \
    || SKIPPED+=("gh login without the project scope (run: gh auth refresh -s project)")
else
  SKIPPED+=("gh login without the project scope (run: gh auth refresh -s project)")
fi
pause
# ──────────────────────────────────────────────────────────────────────────

finish
printf '  Next, in this repository:\n'
step "bash \"$SCRUM_CLI\" init --force-file .github/workflows/scrum-status-sync.yml"
step "bash \"$SCRUM_CLI\" project init --dry-run     (then without --dry-run)"
step "Hide the \"Synced status\" field in every view of the board."
step "Commit and push .github/"
printf '\n'
}

run_wizard "$@"; exit
